/**
 * PriceSparkline - Tiny inline price chart for listing rows
 * Shows 7-14 days of price history as two-line comparison chart
 */

interface PriceObservation {
  observed_at: string;
  delivered_price: number;
}

interface PriceSparklineProps {
  listingPrices: PriceObservation[];
  cpkPrices?: PriceObservation[];
  width?: number;
  height?: number;
  className?: string;
}

export function PriceSparkline({
  listingPrices,
  cpkPrices,
  width = 80,
  height = 28,
  className = '',
}: PriceSparklineProps) {
  if ((!listingPrices || listingPrices.length === 0) && (!cpkPrices || cpkPrices.length === 0)) {
    return <span className="text-xs text-gray-400">—</span>;
  }

  // Sort by date (oldest first)
  const sortedListing = [...listingPrices].sort(
    (a, b) => new Date(a.observed_at).getTime() - new Date(b.observed_at).getTime()
  );

  const sortedCpk = cpkPrices
    ? [...cpkPrices].sort(
        (a, b) => new Date(a.observed_at).getTime() - new Date(b.observed_at).getTime()
      )
    : [];

  // Calculate min/max across both datasets
  const allValues = [
    ...sortedListing.map((p) => p.delivered_price),
    ...sortedCpk.map((p) => p.delivered_price),
  ];
  const min = Math.min(...allValues);
  const max = Math.max(...allValues);
  const range = max - min || 1;
  const medianValues = sortedCpk.length > 0
    ? sortedCpk.map((p) => p.delivered_price).sort((a, b) => a - b)
    : sortedListing.map((p) => p.delivered_price).sort((a, b) => a - b);
  const median = medianValues.length % 2 === 1
    ? medianValues[Math.floor(medianValues.length / 2)]
    : (medianValues[medianValues.length / 2 - 1] + medianValues[medianValues.length / 2]) / 2;

  // Generate SVG path points for listing prices (blue)
  const listingPoints = (sortedListing.length === 1 ? [sortedListing[0], sortedListing[0]] : sortedListing)
    .map((p, idx) => {
      const x = (idx / (sortedListing.length - 1 || 1)) * width;
      const y = height - ((p.delivered_price - min) / range) * (height - 4) - 2;
      return `${x},${y}`;
    })
    .join(' ');

  // Generate SVG path points for CPK prices (orange)
  const cpkPoints = (sortedCpk.length === 1 ? [sortedCpk[0], sortedCpk[0]] : sortedCpk)
    .map((p, idx) => {
      const x = (idx / (sortedCpk.length - 1 || 1)) * width;
      const y = height - ((p.delivered_price - min) / range) * (height - 4) - 2;
      return `${x},${y}`;
    })
    .join(' ');

  // Determine trend color for listing
  const listingCurrent = sortedListing[sortedListing.length - 1]?.delivered_price ?? 0;
  const listingPrevious = sortedListing[0]?.delivered_price ?? listingCurrent;
  const listingChange = listingCurrent - listingPrevious;
  const listingTrendColor =
    listingChange < -0.01 ? '#3b82f6' : // Blue (price dropped)
    listingChange > 0.01 ? '#3b82f6' : // Blue (stable or up, still this listing)
    '#3b82f6'; // Blue (this listing)

  const formatAxisValue = (value: number) => `£${value.toFixed(0)}`;

  return (
    <div
      className={`flex items-stretch justify-center gap-1 ${className}`}
      title="Blue: this listing | Orange: market average"
    >
      <div className="flex h-full flex-col justify-between text-[8px] leading-none text-slate-500" aria-hidden="true">
        <span>{formatAxisValue(max)}</span>
        <span>{formatAxisValue(median)}</span>
        <span>{formatAxisValue(min)}</span>
      </div>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        className="overflow-visible"
      >
        {/* Grid line at middle */}
        <line
          x1="0"
          y1={height / 2}
          x2={width}
          y2={height / 2}
          stroke="#e5e7eb"
          strokeWidth="0.5"
          opacity="0.3"
        />

        {/* CPK price line (orange, if available) */}
        {cpkPoints && (
          <>
            <polyline
              points={cpkPoints}
              fill="none"
              stroke="#f97316"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity="0.6"
            />
            {sortedCpk.length > 0 && (
              <circle
                cx={width}
                cy={height - ((sortedCpk[sortedCpk.length - 1].delivered_price - min) / range) * (height - 4) - 2}
                r="1"
                fill="#f97316"
                opacity="0.6"
              />
            )}
          </>
        )}

        {/* Listing price line (blue) */}
        {sortedListing.length > 0 && (
          <polyline
            points={listingPoints}
            fill="none"
            stroke={listingTrendColor}
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        )}

        {/* Current listing price dot */}
        {sortedListing.length > 0 && (
          <circle
            cx={width}
            cy={height - ((listingCurrent - min) / range) * (height - 4) - 2}
            r="1.5"
            fill={listingTrendColor}
          />
        )}
      </svg>
    </div>
  );
}
